import * as actions from '../../location/location-action/location.action';
import { LocationRecordState } from './location.state';
export const initialState = new LocationRecordState();
export function reducer(state = initialState, {
  type,
  payload
}) {
  if (!type) {
    return state;
  }

  switch (type) {
    case actions.ActionTypes.DO_ADD_LOCATION:
      {
        return Object.assign({}, state, {
          addLoading: true,
          addLoaded: false,
          addFailed: false
        });
      }

    case actions.ActionTypes.DO_UPDATE_LOCATION:
      {
        return Object.assign({}, state, {
          updateLoading: true,
          updateLoaded: false,
          updateFailed: false
        });
      }

    case actions.ActionTypes.GET_LOCATION_LIST:
      {
        return Object.assign({}, state, {
          listLoading: true,
          listLoaded: false,
          listFailed: false
        });
      }

    case actions.ActionTypes.GET_LOCATION_COUNT_ACTION:
      {
        return Object.assign({}, state, {
          countLoading: true,
          countLoaded: false,
          countFailed: false
        });
      }

    case actions.ActionTypes.DO_LOCATION_DELETE:
      {
        return Object.assign({}, state, {
          deleteLoading: true,
          deleteLoaded: false,
          deleteFailed: false
        });
      }

    case actions.ActionTypes.DO_ADD_LOCATION_SUCCESS:
      {
        return Object.assign({}, state, {
          newLocation: payload,
          addLoading: false,
          addLoaded: true,
          addFailed: false
        });
      }

    case actions.ActionTypes.DO_UPDATE_LOCATION_SUCCESS:
      {
        return Object.assign({}, state, {
          updateLocation: payload,
          updateLoading: false,
          updateLoaded: true,
          updateFailed: false
        });
      }

    case actions.ActionTypes.GET_LOCATION_LIST_SUCCESS:
      {
        return Object.assign({}, state, {
          locationList: payload.data,
          listLoading: false,
          listLoaded: true,
          listFailed: false
        });
      }

    case actions.ActionTypes.GET_LOCATION_COUNT_SUCCESS:
      {
        return Object.assign({}, state, {
          locationPagination: payload.data,
          countLoading: false,
          countLoaded: true,
          countFailed: false
        });
      }

    case actions.ActionTypes.DO_LOCATION_DELETE_SUCCESS:
      {
        return Object.assign({}, state, {
          locationDelete: payload,
          deleteLoading: false,
          deleteLoaded: true,
          deleteFailed: false
        });
      }

    case actions.ActionTypes.DO_ADD_LOCATION_FAIL:
      {
        return Object.assign({}, state, {
          newLocation: payload,
          addLoading: false,
          addLoaded: true,
          addFailed: true
        });
      }

    case actions.ActionTypes.DO_UPDATE_LOCATION_FAIL:
      {
        return Object.assign({}, state, {
          updateLocation: payload,
          updateLoading: false,
          updateLoaded: true,
          updateFailed: true
        });
      }

    case actions.ActionTypes.DO_LOCATION_DELETE_FAIL:
      {
        return Object.assign({}, state, {
          deleteLoading: false,
          deleteLoaded: true,
          deleteFailed: true
        });
      }

    case actions.ActionTypes.GET_LOCATION_COUNT_FAIL:
      {
        return Object.assign({}, state, {
          locationDelete: payload,
          countLoading: false,
          countLoaded: true,
          countFailed: true
        });
      }

    case actions.ActionTypes.GET_LOCATION_LIST_FAIL:
      {
        return Object.assign({}, state, {
          listLoading: false,
          listLoaded: true,
          listFailed: true
        });
      }

    default:
      {
        return state;
      }
  }
}
export const newLocation = state => state.newLocation;
export const updateLocation = state => state.updateLocation;
export const locationDelete = state => state.locationDelete;
export const locationList = state => state.locationList;
export const locationPagination = state => state.locationPagination;
export const getLocationListLoading = state => state.listLoading;
export const getLocationListLoaded = state => state.listLoaded;
export const getLocationListFailed = state => state.listFailed;
export const getLocationCountLoading = state => state.countLoading;
export const getLocationCountLoaded = state => state.countLoaded;
export const getLocationCountFailed = state => state.countFailed;
export const getLocationAddLoading = state => state.addLoading;
export const getLocationAddLoaded = state => state.addLoaded;
export const getLocationAddFailed = state => state.addFailed;
export const getLocationUpdateLoading = state => state.updateLoading;
export const getLocationUpdateLoaded = state => state.updateLoaded;
export const getLocationUpdateFailed = state => state.updateFailed;
export const getLocationDeleteLoading = state => state.deleteLoading;
export const getLocationDeleteLoaded = state => state.deleteLoaded;
export const getLocationDeleteFailed = state => state.deleteFailed;
